  --accent: #7aa2ff;
  --accent-hover: #93b4ff;
  --danger: #ef4f5a;
  --danger-hover: #ff6b75;
  --danger-fg: #fff;
  --focus: #ffd166;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
