  border-radius: 4px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 8px; }

.page {
  max-width: 880px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, #0e1116 0%, #0b0d10 100%);
}
.site-header .brand {
  font-weight: 600;
  letter-spacing: 0.02em;
}
.site-header nav a {
  color: var(--text-muted);
  text-decoration: none;
  margin-left: 18px;
}
.site-header nav a:hover { color: var(--text); }

h1 {
  font-size: 1.6rem;
  margin: 0 0 4px;
  font-weight: 600;
}
.subtitle {
  color: var(--text-muted);
  margin: 0 0 24px;
}

.image-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.image-frame {
  background:
    radial-gradient(1200px 500px at 30% 10%, #2a3550 0%, transparent 60%),
    radial-gradient(900px 400px at 80% 80%, #4a2a55 0%, transparent 60%),
    linear-gradient(135deg, #0f1320, #1a1030);
  aspect-ratio: 16 / 10;
  display: grid;
  place-items: center;
  position: relative;
}

.image-frame::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(2px 2px at 20% 30%, #ffffffaa, transparent 50%),
    radial-gradient(1.5px 1.5px at 70% 60%, #ffffff88, transparent 50%),
    radial-gradient(1px 1px at 40% 80%, #ffffff66, transparent 50%),
    radial-gradient(1.5px 1.5px at 85% 20%, #ffffff99, transparent 50%);
  pointer-events: none;
}
.image-frame .label {
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 1.4rem;
  color: #e8e6ff;
  text-shadow: 0 2px 12px rgba(0,0,0,0.6);
  letter-spacing: 0.05em;
}

.image-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  border-top: 1px solid var(--border);
}
.image-meta .info { min-width: 0; }
.image-meta .title {
  font-weight: 600;
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.image-meta .meta {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin: 2px 0 0;
}

.actions {
  display: flex;
  gap: 8px;
  padding: 12px 20px 20px;
  border-top: 1px solid var(--border);
}

.btn {
  font: inherit;
  border-radius: 8px;
  padding: 10px 16px;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  transition: background-color 120ms, border-color 120ms, transform 80ms;
}
.btn:hover { background: #232a33; }
.btn:active { transform: translateY(1px); }
.btn[disabled] { opacity: 0.6; cursor: not-allowed; }

.btn-danger {
  background: var(--danger);
  border-color: transparent;
  color: var(--danger-fg);
}
.btn-danger:hover { background: var(--danger-hover); }

.btn-ghost {
  background: transparent;
}
.btn-ghost:hover { background: #1a1f26; }

.btn .icon {
  width: 16px; height: 16px;
  display: inline-block;
  flex: none;
}

/* Dialog */
.dialog {
  border: 1px solid var(--border-strong);
  background: var(--bg-elev);
  color: var(--text);
  border-radius: 14px;
  padding: 0;
  max-width: 440px;
  width: calc(100% - 32px);
  box-shadow: var(--shadow);
}
.dialog::backdrop {
  background: rgba(4, 6, 10, 0.65);
  backdrop-filter: blur(2px);
}
.dialog[open] {
  animation: dialog-in 140ms ease-out;
}
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(6px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[open] { animation: none; }
}

.dialog-body {
  padding: 22px 22px 8px;
}
.dialog-title {
  margin: 0 0 8px;
  font-size: 1.15rem;
  font-weight: 600;
}
.dialog-text {
  margin: 0;
  color: var(--text-muted);
}
.dialog-filename {
  display: inline-block;
  margin-top: 10px;
  padding: 4px 8px;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.875rem;
  color: var(--text);
}

.dialog-footer {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  padding: 16px 22px 22px;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

@media (max-width: 480px) {
  .image-meta { flex-direction: column; align-items: flex-start; }
  .actions { flex-wrap: wrap; }
  .dialog-footer { flex-direction: column-reverse; }
  .dialog-footer .btn { width: 100%; justify-content: center; }
}

@media (forced-colors: active) {
  .btn, .dialog { border: 1px solid CanvasText; }
  .btn-danger { background: Mark; color: MarkText; }
}
