* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
}

a { color: var(--accent); }
a:hover { color: var(--accent-hover); }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 8px;
  background: var(--bg-elev-2);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 4px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 8px; }

.page {
  max-width: 880px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, #0e1116 0%, #0b0d10 100%);
}
.site-header .brand {
  font-weight: 600;
  letter-spacing: 0.02em;
}
.site-header nav a {
  color: var(--text-muted);
  text-decoration: none;
  margin-left: 18px;
}
.site-header nav a:hover { color: var(--text); }

h1 {
  font-size: 1.6rem;
  margin: 0 0 4px;
  font-weight: 600;
}
.subtitle {
  color: var(--text-muted);
  margin: 0 0 24px;
}

.image-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
