.image-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.image-frame {
  background:
    radial-gradient(1200px 500px at 30% 10%, #2a3550 0%, transparent 60%),
    radial-gradient(900px 400px at 80% 80%, #4a2a55 0%, transparent 60%),
    linear-gradient(135deg, #0f1320, #1a1030);
  aspect-ratio: 16 / 10;
  display: grid;
  place-items: center;
  position: relative;
}

.image-frame::after {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(2px 2px at 20% 30%, #ffffffaa, transparent 50%),
    radial-gradient(1.5px 1.5px at 70% 60%, #ffffff88, transparent 50%),
    radial-gradient(1px 1px at 40% 80%, #ffffff66, transparent 50%),
    radial-gradient(1.5px 1.5px at 85% 20%, #ffffff99, transparent 50%);
  pointer-events: none;
}
.image-frame .label {
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 1.4rem;
  color: #e8e6ff;
  text-shadow: 0 2px 12px rgba(0,0,0,0.6);
  letter-spacing: 0.05em;
}

