(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const url = 'http://localhost:8765/index.html';
  await page.goto(url, { waitUntil: 'networkidle0' });
